import{_ as t,o as a,c as i,ae as o}from"./chunks/framework.Czhw_PXq.js";const g=JSON.parse('{"title":"ADR 019: Frontend UI Refinements and CORS Security Strategy","description":"","frontmatter":{},"headers":[],"relativePath":"adr/019-frontend-ui-and-security.md","filePath":"adr/019-frontend-ui-and-security.md"}'),n={name:"adr/019-frontend-ui-and-security.md"};function r(s,e,l,d,c,u){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-019-frontend-ui-refinements-and-cors-security-strategy" tabindex="-1">ADR 019: Frontend UI Refinements and CORS Security Strategy <a class="header-anchor" href="#adr-019-frontend-ui-refinements-and-cors-security-strategy" aria-label="Permalink to &quot;ADR 019: Frontend UI Refinements and CORS Security Strategy&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted</p><h2 id="date" tabindex="-1">Date <a class="header-anchor" href="#date" aria-label="Permalink to &quot;Date&quot;">​</a></h2><p>2026-03-04</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>During the final polish phase (User Feedback Loop), several usability and visual issues were identified:</p><ol><li><strong>Typography</strong>: The application felt too &quot;generic SaaS&quot; and lacked the gravitas required for a legal/auditing tool.</li><li><strong>Readability</strong>: Long AI-generated summaries were being visually truncated or appearing as large blocks of intimidating text.</li><li><strong>Security</strong>: The separation of frontend (Vercel/Render) and backend (Render) caused CORS issues when strictly closing down access.</li></ol><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><h3 id="_1-typography-aesthetic" tabindex="-1">1. Typography &amp; Aesthetic <a class="header-anchor" href="#_1-typography-aesthetic" aria-label="Permalink to &quot;1. Typography &amp; Aesthetic&quot;">​</a></h3><ul><li><strong>Adoption of Serif Fonts</strong>: We introduced <code>Playfair Display</code> (via Tailwind <code>font-serif</code>) for high-value headings (Dashboard Hero, Analysis Titles, Key Requirements).</li><li><strong>Rationale</strong>: Serif fonts convey authority, tradition, and trustworthiness—key attributes for a &quot;Tender Audit&quot; tool. It visually differentiates the app from standard Bootstrap/Tailwind administrative dashboards.</li></ul><h3 id="_2-dynamic-layouts" tabindex="-1">2. Dynamic Layouts <a class="header-anchor" href="#_2-dynamic-layouts" aria-label="Permalink to &quot;2. Dynamic Layouts&quot;">​</a></h3><ul><li><strong>Problem</strong>: AI-generated titles varied wildly in length (from 10 to 300 characters).</li><li><strong>Solution</strong>: Implemented dynamic font sizing in <code>AnalysisResults.tsx</code>. <ul><li><code>length &gt; 80</code>: Use <code>text-xl</code> (Paragraph style)</li><li><code>length &lt;= 80</code>: Use <code>text-3xl</code> (Headline style)</li></ul></li><li><strong>Layout Refactor</strong>: Moved action buttons (JSON/PDF) to a separate row below the title to prevent horizontal cramping.</li></ul><h3 id="_3-backend-data-constraints" tabindex="-1">3. Backend Data Constraints <a class="header-anchor" href="#_3-backend-data-constraints" aria-label="Permalink to &quot;3. Backend Data Constraints&quot;">​</a></h3><ul><li><strong>Issue</strong>: The backend service <code>GeminiGenkitService.ts</code> was arbitrarily truncating summaries to 100 characters, leading to incomplete sentences.</li><li><strong>Fix</strong>: Increased limit to 500 characters. The database schema uses <code>TEXT</code> (SQLite), which handles this length without schema migration.</li></ul><h3 id="_4-cors-strategy" tabindex="-1">4. CORS Strategy <a class="header-anchor" href="#_4-cors-strategy" aria-label="Permalink to &quot;4. CORS Strategy&quot;">​</a></h3><ul><li><strong>Problem</strong>: <code>Access-Control-Allow-Origin: *</code> is insecure for production.</li><li><strong>Solution</strong>: Implemented a dynamic whitelist approach in <code>server.ts</code>. <ul><li>Usage: <code>process.env.ALLOWED_ORIGINS</code> (Comma-separated list).</li><li>Logic: checks <code>indexOf(origin)</code> or allows all if <code>NODE_ENV !== production</code>.</li><li>Benefit: Strictly limits API access to our known frontend domains while keeping local dev easy.</li></ul></li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><strong>Positive</strong>: Significant improvement in perceived quality and readability. Security posture hardened for production.</li><li><strong>Negative</strong>: Slight increase in CSS complexity (dynamic classes). Need to manage <code>ALLOWED_ORIGINS</code> carefully in deployment environments to avoid blocking legitimate users.</li></ul>',19)])])}const m=t(n,[["render",r]]);export{g as __pageData,m as default};
